"""Backtest output container and persistence."""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

import pandas as pd
import yaml


@dataclass
class BacktestResult:
    """Tabular artifacts generated by one reproducible backtest run."""

    run_id: str
    nav: pd.DataFrame
    signals: pd.DataFrame
    targets: pd.DataFrame
    orders: pd.DataFrame
    fills: pd.DataFrame
    trades: pd.DataFrame
    positions: pd.DataFrame
    risk_events: pd.DataFrame
    summary: dict[str, Any]
    validity: dict[str, Any]

    def save(self, root: str | Path, config_snapshot: dict[str, Any]) -> Path:
        """Persist all run artifacts under a unique directory."""

        directory = Path(root) / self.run_id
        directory.mkdir(parents=True, exist_ok=True)
        for name, frame in (
            ("nav", self.nav),
            ("signals", self.signals),
            ("target_positions", self.targets),
            ("orders", self.orders),
            ("fills", self.fills),
            ("closed_trades", self.trades),
            ("positions", self.positions),
            ("risk_events", self.risk_events),
        ):
            frame.to_parquet(directory / f"{name}.parquet", index=False)
        (directory / "summary.json").write_text(
            json.dumps(self.summary, ensure_ascii=False, indent=2, default=str),
            encoding="utf-8",
        )
        (directory / "validity_report.json").write_text(
            json.dumps(self.validity, ensure_ascii=False, indent=2, default=str),
            encoding="utf-8",
        )
        (directory / "config.snapshot.yaml").write_text(
            yaml.safe_dump(config_snapshot, allow_unicode=True, sort_keys=False),
            encoding="utf-8",
        )
        return directory


def dataclasses_to_frame(items: list[Any]) -> pd.DataFrame:
    """Convert dataclass instances to a DataFrame."""

    return pd.DataFrame([asdict(item) for item in items])
